-- PT114-S2-Q20. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT114-S2-Q20$batch06$ AND q.stimulus=$batch06$Professor Beckstein: American Sign Language is the native language of many North Americans. Therefore, it is not a foreign language, and for that reason alone, no student should be permitted to satisfy the university’s foreign language requirement by learning it.
Professor Sedley: According to your argument, students should not be allowed to satisfy the university’s foreign language requirement by learning French or Spanish either, since they too are the native languages of many North Americans. Yet many students currently satisfy the requirement by studying French or Spanish, and it would be ridiculous to begin prohibiting them from doing so.$batch06$ AND q.prompt=$batch06$Professor Sedley uses which one of the following strategies of argumentation in responding to Professor Beckstein's argument?$batch06$ AND q.correct_choice=$batch06$A$batch06$) THEN RAISE EXCEPTION 'Question changed: PT114-S2-Q20'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT114-S2-Q20$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT114-S2-Q20'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT114-S2-Q20$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$(Sedley) Beckstein's reasoning is flawed.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$French and Spanish are also native languages of many North Americans, so the same reasoning would bar them too, which would be ridiculous.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$Beckstein's logic is: a native language of many North Americans is not foreign, so it cannot meet the requirement. Sedley runs that same logic on French and Spanish and gets an unacceptable result. If the reasoning leads somewhere absurd, the reasoning is broken.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Showing the same reasoning leads to an unacceptable conclusion.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT114-S2-Q20$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$The reasoning is Beckstein's "native language, so not foreign." The other conclusion is barring French and Spanish. It is undesirable because it would be ridiculous.$batch06$), ($batch06$B$batch06$, $batch06$This is the most popular wrong answer. It is close, since Sedley does find a problem with the argument. But he does not show Beckstein's conclusion contradicting Beckstein's own evidence. He shows the reasoning producing a *second* conclusion nobody would accept. Those are different moves.$batch06$), ($batch06$C$batch06$, $batch06$Sedley never questions Beckstein's authority.$batch06$), ($batch06$D$batch06$, $batch06$No facts get a new explanation.$batch06$), ($batch06$E$batch06$, $batch06$Sedley rejects Beckstein's conclusion. He does not agree with it.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT114-S2-Q20$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
